    function OpenDetailsPopUp(action, bookingNumber, iata) {
        $.ajax({
            type: "POST",
            url: "/agent/WebServices/Booking/Booking.asmx/" + action,
            data: "{ bookingNumber: '" + bookingNumber + "', iata: '" + iata + "'}",
            contentType: "application/json; charset=utf-8",
            dataType: "json",
            success: function (html) {
                if (html.d != "") {
                    $(document).bind('cbox_complete', function () {
                        $.colorbox.resize();
                    });
                    $.colorbox({ html: html.d, closeButton: false });
                }
            }
        });
    }
