function ChangeDay(day) {
    var control = document.getElementById("uxDayHidden");
    control.value = day;
    var showDayControl = document.getElementById("uxShowDay");
    showDayControl.value = true;
    __doPostBack('ShowItinView','');
}
function ChangeToCalView() {
    var control = document.getElementById("uxDayHidden");
    control.value = '1';
    var showDayControl = document.getElementById("uxShowDay");
    showDayControl.value = false;
    __doPostBack('ShowItinView','');
}
function ChangeToListView() {
    var control = document.getElementById("uxDayHidden");
    control.value = '1';
    var showDayControl = document.getElementById("uxShowDay");
    showDayControl.value = true;
    __doPostBack('ShowItinView','');
}
function CloseItinView() {
    var showItinControl = document.getElementById("uxShowItin");
    showItinControl.value = false;
    __doPostBack('ShowItinView','');
}
function ShowItinView() {
    var showItinControl = document.getElementById("uxShowItin");
    showItinControl.value = true;
    __doPostBack('ShowItinView','');
}





















